    if (str == null) {
        return null;
    }

    // Find the first occurrence of an escaped character
    int start = str.indexOf('\\');
    if (start == -1) {
        // If there are no escaped characters, return the original string
        return str;
    }

    // Create a new string builder to assemble the unescaped string
    StringBuilder sb = new StringBuilder(str.length());

    // Loop through the characters in the original string
    for (int i = 0; i < str.length(); i++) {
        char c = str.charAt(i);

        // If the current character is an escaped character, determine which one and append the appropriate character
        if (c == '\\') {
            char nextChar = str.charAt(i + 1);
            if (nextChar == 'n') {
                sb.append('\n');
                i++;
            } else if (nextChar == 't') {
                sb.append('\t');
                i++;
            } else if (nextChar == '\\') {
                sb.append('\\');
                i++;
            } else {
                // If the next character is not a recognized escaped character, append the current character and advance to the next character
                sb.append(c);
            }
        } else {
            // If the current character is not an escaped character, append it
            sb.append(c);
        }
    }

    return sb.toString();
}

