public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    // Load thread snapshots from file
    List<ThreadSnapshot> threadSnapshots = parseFromFile(file);

    // Filter thread snapshots based on time ranges
    for (int i = 0; i < threadSnapshots.size(); i++) {
        ThreadSnapshot threadSnapshot = threadSnapshots.get(i);
        ProfileAnalyzeTimeRange timeRange = timeRanges.get(i);
        if (timeRange.getStartTime() <= threadSnapshot.getStartTime() && threadSnapshot.getStartTime() <= timeRange.getEndTime()) {
            threadSnapshots.add(threadSnapshot);
        }
    }

    return threadSnapshots;
}
